function inline(text) {
  const escaped = text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  // Split out code spans first so the other rules never touch them.
  return escaped
    .split(/(`[^`]*`)/)
    .map(part => {
      if (/^`[^`]*`$/.test(part)) return `<code>${part.slice(1, -1)}</code>`;
      return part
        .replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>")
        .replace(/\*(.+?)\*/g, "<em>$1</em>")
        .replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, '<a href="$2">$1</a>');
    })
    .join("");
}

function markdownToHtml(source) {
  const out = [];
  let paragraph = [];
  let list = [];

  const flush = () => {
    if (paragraph.length) out.push(`<p>${inline(paragraph.join(" "))}</p>`);
    if (list.length) out.push("<ul>", ...list.map(item => `<li>${inline(item)}</li>`), "</ul>");
    paragraph = [];
    list = [];
  };

  for (const raw of source.split(/\r?\n/)) {
    const line = raw.trimEnd();
    const heading = line.match(/^(#{1,6}) (.*)$/);
    if (line.trim() === "") {
      flush();
    } else if (heading) {
      flush();
      const level = heading[1].length;
      out.push(`<h${level}>${inline(heading[2].trim())}</h${level}>`);
    } else if (line.startsWith("- ")) {
      if (paragraph.length) flush();
      list.push(line.slice(2).trim());
    } else {
      if (list.length) flush();
      paragraph.push(line.trim());
    }
  }
  flush();
  return out.join("\n");
}

unitTests:
test("inline rules", () => {
  checkEq(inline("**bold** and *soft*"), "<strong>bold</strong> and <em>soft</em>");
  checkEq(inline("see [docs](https://x.dev/a)"), 'see <a href="https://x.dev/a">docs</a>');
  checkEq(inline("a < b & c > d"), "a &lt; b &amp; c &gt; d");
  checkEq(inline("use `**not bold**` here"), "use <code>**not bold**</code> here");
  checkEq(inline("`<tag>`"), "<code>&lt;tag&gt;</code>");
});

test("the example", () => {
  checkEq(markdownToHtml("# Notes

Some **bold** and *soft* text with `code`.

- one
- [two](https://example.com)"),
    '<h1>Notes</h1>
<p>Some <strong>bold</strong> and <em>soft</em> text with <code>code</code>.</p>
<ul>
<li>one</li>
<li><a href="https://example.com">two</a></li>
</ul>');
});

test("blocks", () => {
  checkEq(markdownToHtml("line one
line two

### Small"), "<p>line one line two</p>
<h3>Small</h3>");
  checkEq(markdownToHtml("- a
- b
text after"), "<ul>
<li>a</li>
<li>b</li>
</ul>
<p>text after</p>");
  checkEq(markdownToHtml("####### seven"), "<p>####### seven</p>");
  checkEq(markdownToHtml("

"), "");
});

